import type { Account, MarketAnalysis, MarketPricePoint, MarketSnapshot, Portfolio } from "../domain/types.js";

function escapeHtml(value: string): string {
  return value.replace(/[&<>'"]/g, (character) => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    "'": "&#39;",
    '"': "&quot;",
  })[character]!);
}

function credits(value: number): string {
  return new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 }).format(value);
}

function percent(value: number): string {
  return `${Math.round(value * 100)}¢`;
}

function volatility(value: number): string {
  return `${(value * 100).toFixed(value * 100 >= 10 ? 0 : 1)}¢ avg move`;
}

function pulseTime(value: string): string {
  const date = new Date(value);
  if (Number.isNaN(date.valueOf())) return value;
  const elapsedMinutes = Math.max(0, Math.floor((Date.now() - date.valueOf()) / 60_000));
  if (elapsedMinutes < 60) return `${Math.max(1, elapsedMinutes)}m`;
  if (elapsedMinutes < 24 * 60) return `${Math.floor(elapsedMinutes / 60)}h`;
  return new Intl.DateTimeFormat(undefined, { month: "short", day: "numeric" }).format(date);
}

const analysisSectionPattern = /(?:^|\n\s*\n)(Pulse|Catalysts|Counter-signals|Watch):\s*([\s\S]*?)(?=\n\s*\n(?:Pulse|Catalysts|Counter-signals|Watch):|$)/gi;

function analysisMarkup(body: string): string {
  const sections: Array<{ title: string; body: string }> = [];
  for (const match of body.matchAll(analysisSectionPattern)) {
    const title = match[1]?.trim();
    const sectionBody = match[2]?.trim();
    if (title && sectionBody) sections.push({ title, body: sectionBody });
  }
  if (sections.length === 0) return `<p class="analysis-loading">${escapeHtml(body)}</p>`;
  return `<div class="analysis-sections">${sections.map((section) => `<section class="analysis-section"><h3>${escapeHtml(section.title)}</h3><p>${escapeHtml(section.body)}</p></section>`).join("")}</div>`;
}

function analysisSources(analysis: MarketAnalysis | null): string {
  if (!analysis) return "";
  const sources = new Map<string, string>();
  for (const post of analysis.posts) {
    try {
      const url = new URL(post.url);
      if (url.protocol === "https:" || url.protocol === "http:") {
        sources.set(url.toString(), post.handle.startsWith("@") ? post.handle : `@${post.handle}`);
      }
    } catch {
      // Ignore malformed model output; source cards should never break the market page.
    }
  }
  for (const source of analysis.sources) {
    try {
      const url = new URL(source);
      if ((url.protocol === "https:" || url.protocol === "http:") && !sources.has(url.toString())) {
        sources.set(url.toString(), "X source");
      }
    } catch {
      // Ignore malformed citations from an upstream response.
    }
  }
  if (sources.size === 0) return "";
  return `<span>Sources</span>${[...sources.entries()].slice(0, 8).map(([url, label]) => `<a class="analysis-source" href="${escapeHtml(url)}" target="_blank" rel="noreferrer">${escapeHtml(label)} ↗</a>`).join("")}`;
}

