/** X's mark, so the button reads as an X sign-in rather than a generic link. */
const X_MARK = `<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18.9 2H22l-7.1 8.1L23.2 22h-6.5l-5.1-6.7L5.8 22H2.7l7.6-8.7L1.2 2h6.7l4.6 6.1L18.9 2Zm-1.1 18h1.7L7.3 3.8H5.5L17.8 20Z"/></svg>`;

/**
 * The sign-in button points at /auth/x/connect/start, NOT /auth/x/start.
 * The latter is startBot() — it authorises the market bot account, so exposing
 * it as a public login would let any visitor overwrite the bot's credentials
 * with their own. startTrader() is the visitor path.
 */
function navAuth(account: Account | null): string {
  if (account) {
    return `<span class="whoami"><span class="dot"></span>Signed in as <b>@${escapeHtml(account.handle.replace(/^@/, ""))}</b></span>`;
  }
  return `<a class="signin" href="/auth/x/connect/start">${X_MARK}Sign in with X</a>`;
}

function layout(content: string, title: string, account: Account | null = null): string {
  return `<!doctype html>
  <html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escapeHtml(title)} · Threadline</title><style>${styles}</style></head>
  <body><main class="shell"><nav class="nav"><a href="/" class="brand">thread<i>line</i></a><span class="nav-links"><a href="/">Markets</a><a href="/portfolio">Portfolio</a><a href="/live" class="live"><i></i>Live</a></span>${navAuth(account)}</nav>${content}</main></body></html>`;
}

export function marketIndexPage(markets: MarketSnapshot[], account: Account | null = null): string {
  const cards = markets.length === 0
    ? `<p class="empty">No markets yet. Mention the bot with <b>market this</b> to create the first one.</p>`
    : markets.map(({ market, priceYes, priceNo }) => `
      <a class="market-card" href="/markets/${market.id}">
        <span class="eyebrow">Open market · closes ${new Date(market.closesAt).toLocaleDateString()}</span>
        <h2>${escapeHtml(market.question)}</h2>
        <div class="prices"><div class="price yes"><span>YES</span><b>${percent(priceYes)}</b></div><div class="price no"><span>NO</span><b>${percent(priceNo)}</b></div></div>
      </a>`).join("");
  return layout(`<section class="list"><div><span class="eyebrow">Prediction markets from X conversations</span><h1 style="font-size:clamp(42px,7vw,84px);margin-bottom:8px">Every argument has odds.</h1><p style="color:var(--muted);max-width:620px">Threadline turns public arguments into live markets. Your account history seeds play credits; your trades move the odds.</p></div>${cards}</section>`, "Markets", account);
}

export function portfolioPage(portfolio: Portfolio): string {
  const { account, positions } = portfolio;
  const cards = positions.length === 0
    ? `<div class="panel empty-portfolio"><b>No open positions yet.</b><p>Browse a market and put your Karma behind a view.</p><a href="/markets">Explore markets →</a></div>`
    : positions.map((item) => {
      const holdings = [item.position.yesShares > 0.0001 ? `${item.position.yesShares.toFixed(1)} YES` : "", item.position.noShares > 0.0001 ? `${item.position.noShares.toFixed(1)} NO` : ""].filter(Boolean).join(" · ");
      const pnlClass = item.openPnl > 0.0001 ? "positive" : item.openPnl < -0.0001 ? "negative" : "";
      const pnlSign = item.openPnl > 0 ? "+" : "";
      return `<a class="panel portfolio-position" href="/markets/${item.market.id}"><div><span class="eyebrow">${escapeHtml(item.market.status)} · ${holdings}</span><h2>${escapeHtml(item.market.question)}</h2></div><div class="portfolio-metric"><span>YES</span><b>${percent(item.priceYes)}</b></div><div class="portfolio-metric"><span>Exit value</span><b>${credits(item.estimatedExitValue)} cr</b></div><div class="portfolio-metric"><span>Open P&L</span><b class="${pnlClass}">${pnlSign}${credits(item.openPnl)} cr</b></div><span class="position-link">Manage →</span></a>`;
    }).join("");
  return layout(`<section class="portfolio"><div class="portfolio-head"><div><span class="eyebrow">@${escapeHtml(account.handle)} · X-linked Karma wallet</span><h1>Your positions.</h1></div><p>${positions.length} open ${positions.length === 1 ? "market" : "markets"}</p></div><div class="equity-grid"><div class="equity-card"><span>Available Karma</span><b>${credits(account.availableBalance)} cr</b></div><div class="equity-card"><span>Open exit value</span><b>${credits(portfolio.estimatedExitValue)} cr</b></div><div class="equity-card"><span>Total equity</span><b>${credits(portfolio.totalEquity)} cr</b></div></div><div class="portfolio-list">${cards}</div></section>`, "Portfolio", account);
}

export function marketPage(snapshot: MarketSnapshot, account: Account | null, history: MarketPricePoint[], isLinked: boolean): string {
  const { market } = snapshot;
  const author = `@${market.sourcePost.authorHandle}`;
  const pulsePosts = (market.analysis?.posts ?? []).filter((post) => {
    try {
      const url = new URL(post.url);
      return (url.protocol === "https:" || url.protocol === "http:") && post.handle && post.text && post.createdAt && post.relevance;
    } catch {
      return false;
    }
  }).slice(0, 8).map((post) => `<a class="pulse-post" href="${escapeHtml(post.url)}" target="_blank" rel="noreferrer"><span class="pulse-post-meta"><b>${escapeHtml(post.handle.startsWith("@") ? post.handle : `@${post.handle}`)}</b><span>${escapeHtml(pulseTime(post.createdAt))}</span></span><q>${escapeHtml(post.text)}</q><small>${escapeHtml(post.relevance)}</small></a>`).join("");
  const canTrade = Boolean(isLinked && account);
  const trader = account ? `@${account.handle}` : "";
  const balance = account === null ? "" : `${credits(account.availableBalance)} credits`;
  const ageYears = account ? Math.max(0, (Date.now() - new Date(account.accountCreatedAt).valueOf()) / (365.2425 * 24 * 60 * 60 * 1000)) : 0;
  const medianImpressions = account?.medianImpressions === null || account?.medianImpressions === undefined ? "No sample" : credits(account.medianImpressions);
  const connection = canTrade
    ? `<span class="linked">● X account linked</span>`
    : `<a class="connect" href="/auth/x/connect/start?returnTo=${encodeURIComponent(`/markets/${market.id}`)}">Link your X account</a>`;
  const tradePanel = canTrade ? `
        ${connection}
        <div class="wallet">Your X-linked wallet<br><a href="https://x.com/${escapeHtml(account!.handle.replace(/^@/, ""))}" target="_blank" rel="noreferrer"><b>${escapeHtml(trader)}</b></a> · <b id="wallet-balance">${balance}</b></div>
        <div class="market-metrics"><div class="market-metric"><span>Liquidity</span><b id="liquidity-depth">${credits(snapshot.metrics.liquidityDepth)} cr</b></div><div class="market-metric"><span>Volatility</span><b id="volatility">${volatility(snapshot.metrics.volatility)}</b></div><div class="market-metric"><span>Activity</span><b id="activity-count">${snapshot.metrics.activityCount} ticks</b></div></div>
        <div class="karma-card"><div class="karma-cell"><span>Karma seed</span><b>${credits(account!.karmaSeed)}</b></div><div class="karma-cell"><span>Account age</span><b>${ageYears.toFixed(1)}y</b></div><div class="karma-cell"><span>Posts</span><b>${credits(account!.postCount)}</b></div><div class="karma-cell"><span>Median reach</span><b>${medianImpressions}</b></div><div class="karma-cell"><span>Sampled posts</span><b>${credits(account!.impressionSampleSize)}</b></div><div class="karma-cell"><span>How it works</span><b>Public X history</b></div></div>
        <form class="trade-form" id="trade-form"><div class="trade-modes"><button class="trade-mode active" type="button" data-mode="BUY">Buy</button><button class="trade-mode" type="button" data-mode="SELL">Sell</button></div><div class="outcomes"><button class="outcome yes active" type="button" data-outcome="YES">YES</button><button class="outcome no" type="button" data-outcome="NO">NO</button></div><div class="position"><span>Your position</span><b id="position-shares">${snapshot.position ? `${snapshot.position.yesShares.toFixed(1)} YES · ${snapshot.position.noShares.toFixed(1)} NO` : "No shares yet"}</b></div><label id="trade-label" for="trade-amount" style="color:var(--muted);font-size:13px">Play credits to spend</label><input id="trade-amount" type="number" min="1" max="1000" value="25" required><div class="quick-spend" id="quick-spend"><button type="button" data-spend="10">10</button><button type="button" data-spend="25">25</button><button type="button" data-spend="100">100</button></div><button class="trade" type="submit">Buy YES</button><p class="notice" id="notice">Trades settle in play credits only. Local demo flow is marked on the chart.</p></form>`
    : `${connection}<div class="wallet"><b>Trade with your own Karma wallet.</b><br>Link X to create your local Threadline account and take a position.</div><div class="market-metrics"><div class="market-metric"><span>Liquidity</span><b id="liquidity-depth">${credits(snapshot.metrics.liquidityDepth)} cr</b></div><div class="market-metric"><span>Volatility</span><b id="volatility">${volatility(snapshot.metrics.volatility)}</b></div><div class="market-metric"><span>Activity</span><b id="activity-count">${snapshot.metrics.activityCount} ticks</b></div></div>`;
  const criteria = market.resolutionCriteria.map((criterion) => escapeHtml(criterion)).join(" ");
  return layout(`
    <section class="market-grid" id="market" data-market-id="${market.id}" data-trader-id="${account?.xUserId ?? ""}" data-can-trade="${canTrade}">
      <article class="hero">
        <span class="eyebrow">${market.status === "OPEN" ? "Open market" : escapeHtml(market.status)}</span>
        <h1>${escapeHtml(market.question)}</h1>
        <a class="source" href="${escapeHtml(market.sourcePost.url)}" target="_blank" rel="noreferrer">Source post by ${escapeHtml(author)} ↗</a>
        <section class="market-analysis" aria-live="polite"><div class="market-analysis-head"><i></i>Market AI analysis · Grok <em>X pulse · context only</em></div><div id="market-analysis" data-ready="${market.analysis && market.analysis.posts.length ? "true" : "false"}" class="${market.analysis && market.analysis.posts.length ? "" : "loading"}">${market.analysis && market.analysis.posts.length ? analysisMarkup(market.analysis.body) : `<p class="analysis-loading">Searching relevant past and current X posts for market context…</p>`}</div><div class="analysis-sources" id="analysis-sources">${analysisSources(market.analysis)}</div><p class="analysis-note">Observed X discussion can inform context, but never resolves this market. Resolution criteria control settlement.</p></section>
        <div class="criteria"><strong>Resolution criteria</strong>${criteria}</div>
        <div class="facts"><div class="fact"><span>Closes</span><b>${new Date(market.closesAt).toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" })}</b></div><div class="fact"><span>Liquidity depth</span><b>${credits(snapshot.metrics.liquidityDepth)} credits</b></div><div class="fact"><span>Source</span><b>${escapeHtml(author)}</b></div></div>
      </article>
      <aside class="panel">
        <h2>Take a position</h2>
        <div class="prices"><div class="price yes"><span>YES</span><b id="yes-price">${percent(snapshot.priceYes)}</b></div><div class="price no"><span>NO</span><b id="no-price">${percent(snapshot.priceNo)}</b></div></div>
        ${tradePanel}
      </aside>
      <section class="panel pulse-strip" aria-label="Live X feed"><div class="pulse-feed-head"><b>Live X feed</b><span class="pulse-hint">Scroll →</span><span id="pulse-updated">${market.analysis?.posts.length ? `Updated ${new Date(market.analysis.generatedAt).toLocaleTimeString([], { hour: "numeric", minute: "2-digit" })}` : "Loading…"}</span><button class="pulse-refresh" id="pulse-refresh" type="button">Refresh pulse</button></div><div class="pulse-feed-list" id="pulse-feed" tabindex="0" aria-label="Scrollable X market context"><div class="pulse-feed-track">${pulsePosts || `<p class="pulse-feed-empty">Searching relevant X posts…</p>`}</div></div></section>
      <section class="panel chart-panel"><div class="chart-head"><div><span class="eyebrow">Live market signal</span><h2>YES probability</h2></div><p id="chart-value">${percent(snapshot.priceYes)} now</p></div><div class="chart-wrap"><canvas id="price-chart" aria-label="YES price history chart. Hover to inspect a price point."></canvas><div id="chart-tooltip" class="chart-tooltip" aria-hidden="true"><b id="tooltip-price"></b><span id="tooltip-detail"></span><span id="tooltip-time"></span></div></div><div class="chart-labels"><span id="chart-start">Market open</span><span class="pulse" id="pulse-label">● local demo flow · ${snapshot.metrics.demoActivityCount} ticks</span></div></section>
    </section>
    <script>
      (() => {
        const root = document.getElementById('market'); const id = root.dataset.marketId; const userId = root.dataset.traderId; const canTrade = root.dataset.canTrade === 'true';
        let outcome = 'YES'; let mode = 'BUY'; let position = ${JSON.stringify(snapshot.position)} || {yesShares: 0, noShares: 0}; let points = ${JSON.stringify(history)}; let hoveredIndex = null; const form = document.getElementById('trade-form'); const notice = document.getElementById('notice'); const chart = document.getElementById('price-chart'); const tooltip = document.getElementById('chart-tooltip'); const amountInput = document.getElementById('trade-amount');
        const analysis = document.getElementById('market-analysis'); const analysisSources = document.getElementById('analysis-sources'); const pulseFeed = document.getElementById('pulse-feed'); const pulseUpdated = document.getElementById('pulse-updated'); const pulseRefresh = document.getElementById('pulse-refresh');
        const formatPulseTime = value => { const date = new Date(value); if (Number.isNaN(date.valueOf())) return value; const minutes = Math.max(0, Math.floor((Date.now() - date.valueOf()) / 60000)); if (minutes < 60) return Math.max(1, minutes) + 'm'; if (minutes < 1440) return Math.floor(minutes / 60) + 'h'; return new Intl.DateTimeFormat(undefined, {month:'short', day:'numeric'}).format(date); };
        const setPulseUpdated = value => { if (pulseUpdated) pulseUpdated.textContent = value; };
       const validPulsePost = post => post && typeof post.url === 'string' && typeof post.handle === 'string' && typeof post.text === 'string' && typeof post.createdAt === 'string' && typeof post.relevance === 'string';
        const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches; let pulseTrack = null; let pulseCycleWidth = 0; let pulseOffset = 0; let pulsePaused = false; let pulsePauseUntil = 0; let lastPulseFrame = performance.now();
        const pausePulse = (duration = 3000) => { pulsePauseUntil = Math.max(pulsePauseUntil, performance.now() + duration); };
        const getPulseTrack = () => { if (!pulseFeed) return null; let track = pulseFeed.querySelector('.pulse-feed-track'); if (!track) { track = document.createElement('div'); track.className = 'pulse-feed-track'; while (pulseFeed.firstChild) track.append(pulseFeed.firstChild); pulseFeed.append(track); } return track; };
        const handOffPulseToScroll = (duration = 3000) => { if (!pulseFeed || !pulseTrack) return; const visualOffset = pulseFeed.scrollLeft + pulseOffset; pulseOffset = 0; pulseTrack.style.transform = 'translate3d(0,0,0)'; pulseFeed.scrollLeft = pulseCycleWidth ? visualOffset % pulseCycleWidth : visualOffset; pausePulse(duration); };
        const setupPulseLoop = () => { pulseTrack = getPulseTrack(); if (!pulseFeed || !pulseTrack) return; pulseTrack.querySelectorAll('[data-pulse-clone]').forEach(node => node.remove()); pulseCycleWidth = 0; pulseOffset = 0; pulseTrack.style.transform = 'translate3d(0,0,0)'; const originals = [...pulseTrack.children]; if (prefersReducedMotion || originals.length < 2 || pulseTrack.scrollWidth <= pulseFeed.clientWidth + 2) return; const originalWidth = pulseTrack.scrollWidth; originals.forEach(item => { const clone = item.cloneNode(true); clone.dataset.pulseClone = 'true'; clone.setAttribute('aria-hidden', 'true'); clone.tabIndex = -1; clone.querySelectorAll('a,button,[tabindex]').forEach(node => node.tabIndex = -1); pulseTrack.append(clone); }); pulseCycleWidth = originalWidth; pulseFeed.scrollLeft %= pulseCycleWidth; };
        const advancePulse = now => { const elapsed = Math.min(50, now - lastPulseFrame); lastPulseFrame = now; if (pulseTrack && !prefersReducedMotion && !pulsePaused && now >= pulsePauseUntil && document.visibilityState === 'visible' && pulseCycleWidth > 0) { pulseOffset = (pulseOffset + elapsed * .05) % pulseCycleWidth; pulseTrack.style.transform = 'translate3d(' + (-pulseOffset) + 'px,0,0)'; } requestAnimationFrame(advancePulse); };
        const renderAnalysis = body => { if (!analysis) return; analysis.replaceChildren(); const pattern = /(?:^|\\n\\s*\\n)(Pulse|Catalysts|Counter-signals|Watch):\\s*([\\s\\S]*?)(?=\\n\\s*\\n(?:Pulse|Catalysts|Counter-signals|Watch):|$)/gi; const sections = [...body.matchAll(pattern)].map(match => ({title:match[1]?.trim(), body:match[2]?.trim()})).filter(section => section.title && section.body); if (!sections.length) { const fallback = document.createElement('p'); fallback.className = 'analysis-loading'; fallback.textContent = body; analysis.append(fallback); return; } const grid = document.createElement('div'); grid.className = 'analysis-sections'; sections.forEach(section => { const item = document.createElement('section'); item.className = 'analysis-section'; const title = document.createElement('h3'); title.textContent = section.title; const text = document.createElement('p'); text.textContent = section.body; item.append(title, text); grid.append(item); }); analysis.append(grid); };
        const renderAnalysisSources = value => { if (!analysisSources) return; analysisSources.replaceChildren(); const links = new Map(); const append = (urlValue, label) => { try { const url = new URL(urlValue); if ((url.protocol === 'https:' || url.protocol === 'http:') && !links.has(url.toString())) links.set(url.toString(), label); } catch {} }; (Array.isArray(value.posts) ? value.posts : []).filter(validPulsePost).forEach(post => append(post.url, post.handle.startsWith('@') ? post.handle : '@' + post.handle)); (Array.isArray(value.sources) ? value.sources : []).filter(source => typeof source === 'string').forEach(source => append(source, 'X source')); if (!links.size) return; const heading = document.createElement('span'); heading.textContent = 'Sources'; analysisSources.append(heading); [...links.entries()].slice(0, 8).forEach(([url, label]) => { const link = document.createElement('a'); link.className = 'analysis-source'; link.href = url; link.target = '_blank'; link.rel = 'noreferrer'; link.textContent = label + ' ↗'; analysisSources.append(link); }); };
        const renderPulseFeed = posts => { if (!pulseFeed) return; pulseFeed.replaceChildren(); const track = document.createElement('div'); track.className = 'pulse-feed-track'; pulseFeed.append(track); const items = Array.isArray(posts) ? posts.filter(validPulsePost).slice(0, 8) : []; if (!items.length) { pulseCycleWidth = 0; const empty = document.createElement('p'); empty.className = 'pulse-feed-empty'; empty.textContent = 'No source-verified X posts were found for this pulse.'; track.append(empty); return; } items.forEach(post => { try { const url = new URL(post.url); if (url.protocol !== 'https:' && url.protocol !== 'http:') return; const card = document.createElement('a'); card.className = 'pulse-post'; card.href = url.toString(); card.target = '_blank'; card.rel = 'noreferrer'; const meta = document.createElement('span'); meta.className = 'pulse-post-meta'; const handle = document.createElement('b'); handle.textContent = post.handle.startsWith('@') ? post.handle : '@' + post.handle; const time = document.createElement('span'); time.textContent = formatPulseTime(post.createdAt); meta.append(handle, time); const quote = document.createElement('q'); quote.textContent = post.text; const relevance = document.createElement('small'); relevance.textContent = post.relevance; card.append(meta, quote, relevance); track.append(card); } catch {} }); setupPulseLoop(); };
        const validAnalysis = payload => payload && payload.analysis && typeof payload.analysis.body === 'string' && Array.isArray(payload.analysis.posts) && typeof payload.analysis.generatedAt === 'string';
        const applyAnalysis = payload => { const value = payload.analysis; renderAnalysis(value.body); renderAnalysisSources(value); analysis.dataset.ready = 'true'; analysis.classList.remove('loading'); renderPulseFeed(value.posts); setPulseUpdated('Updated ' + new Intl.DateTimeFormat(undefined, {hour:'numeric', minute:'2-digit'}).format(new Date(value.generatedAt))); };
        const loadAnalysis = async refreshPulse => { if (pulseRefresh) { pulseRefresh.disabled = true; pulseRefresh.textContent = refreshPulse ? 'Refreshing pulse…' : 'Loading pulse…'; } try { const response = await fetch('/api/markets/' + id + '/analysis', {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({refresh:refreshPulse})}); const payload = await response.json().catch(() => null); if (!response.ok || !validAnalysis(payload)) throw new Error(); applyAnalysis(payload); } catch { if (analysis.dataset.ready === 'true') setPulseUpdated('Refresh failed — showing the last pulse'); else { analysis.textContent = 'Market AI analysis is unavailable right now. Review the source post and resolution criteria.'; analysis.classList.remove('loading'); setPulseUpdated('Analysis unavailable'); } } finally { if (pulseRefresh) { pulseRefresh.disabled = false; pulseRefresh.textContent = 'Refresh pulse'; } } };
        if (analysis && analysis.dataset.ready !== 'true') void loadAnalysis(false); if (pulseRefresh) pulseRefresh.addEventListener('click', () => void loadAnalysis(true)); if (pulseFeed) { setupPulseLoop(); pulseFeed.addEventListener('focusin', () => { handOffPulseToScroll(); pulsePaused = true; }); pulseFeed.addEventListener('focusout', () => { pulsePaused = false; }); pulseFeed.addEventListener('touchstart', () => { handOffPulseToScroll(); pulsePaused = true; }, {passive:true}); pulseFeed.addEventListener('touchend', () => { pulsePaused = false; pausePulse(4000); }, {passive:true}); pulseFeed.addEventListener('wheel', () => handOffPulseToScroll(4000), {passive:true}); pulseFeed.addEventListener('scroll', () => handOffPulseToScroll(4000), {passive:true}); pulseFeed.addEventListener('keydown', event => { if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return; event.preventDefault(); handOffPulseToScroll(5000); pulseFeed.scrollBy({left:event.key === 'ArrowRight' ? 240 : -240, behavior:'smooth'}); }); window.addEventListener('resize', setupPulseLoop); if (!prefersReducedMotion) requestAnimationFrame(advancePulse); }
        const money = value => new Intl.NumberFormat('en-US', {maximumFractionDigits: 0}).format(value) + ' credits';
        const formatVolatility = value => (value * 100).toFixed(value * 100 >= 10 ? 0 : 1) + '¢ avg move';
        const ownedShares = () => outcome === 'YES' ? position.yesShares : position.noShares;
        const syncTradeForm = () => { if (!canTrade) return; const selling = mode === 'SELL'; document.querySelectorAll('[data-mode]').forEach(button => button.classList.toggle('active', button.dataset.mode === mode)); document.querySelectorAll('[data-outcome]').forEach(button => button.classList.toggle('active', button.dataset.outcome === outcome)); document.getElementById('trade-label').textContent = selling ? 'Shares to sell' : 'Play credits to spend'; document.getElementById('quick-spend').style.display = selling ? 'none' : 'flex'; amountInput.min = selling ? '0.01' : '1'; amountInput.max = selling ? String(Math.max(0, ownedShares())) : '1000'; if (selling && Number(amountInput.value) > ownedShares()) amountInput.value = ownedShares() > 0 ? ownedShares().toFixed(2) : ''; form.querySelector('.trade').textContent = (selling ? 'Sell ' : 'Buy ') + outcome; };
        const drawChart = () => { const ctx = chart.getContext('2d'); const bounds = chart.getBoundingClientRect(); const ratio = window.devicePixelRatio || 1; chart.width = Math.max(1, Math.round(bounds.width * ratio)); chart.height = Math.max(1, Math.round(bounds.height * ratio)); ctx.scale(ratio, ratio); const width = bounds.width; const height = bounds.height; ctx.clearRect(0, 0, width, height); const plotted = points.length ? points : [{priceYes: .5, recordedAt: new Date().toISOString(), kind: 'OPEN'}]; const values = plotted.map(point => point.priceYes); const times = plotted.map(point => new Date(point.recordedAt).valueOf()).map(time => Number.isFinite(time) ? time : Date.now()); const minTime = Math.min(...times); const maxTime = Math.max(minTime + 1, ...times); const padding = 18; const minValue = Math.min(...values); const maxValue = Math.max(...values); const cushion = Math.max(.03, (maxValue - minValue) * .24); let lowerBound = minValue - cushion; let upperBound = maxValue + cushion; if (lowerBound < 0) { upperBound = Math.min(1, upperBound - lowerBound); lowerBound = 0; } if (upperBound > 1) { lowerBound = Math.max(0, lowerBound - (upperBound - 1)); upperBound = 1; } const valueRange = Math.max(.01, upperBound - lowerBound); const x = index => values.length === 1 ? width / 2 : width * index / (values.length - 1); const y = value => padding + (upperBound - value) / valueRange * (height - padding * 2); const area = ctx.createLinearGradient(0, 0, 0, height); area.addColorStop(0, 'rgba(213,255,82,.32)'); area.addColorStop(1, 'rgba(213,255,82,0)'); ctx.beginPath(); values.forEach((value, index) => index === 0 ? ctx.moveTo(x(index), y(value)) : ctx.lineTo(x(index), y(value))); ctx.lineTo(x(values.length - 1), height - padding); ctx.lineTo(x(0), height - padding); ctx.closePath(); ctx.fillStyle = area; ctx.fill(); ctx.beginPath(); values.forEach((value, index) => index === 0 ? ctx.moveTo(x(index), y(value)) : ctx.lineTo(x(index), y(value))); ctx.strokeStyle = '#d5ff52'; ctx.lineWidth = 2.5; ctx.stroke(); if (hoveredIndex !== null && values[hoveredIndex] !== undefined) { const selected = plotted[hoveredIndex]; const previous = values[Math.max(0, hoveredIndex - 1)]; const movement = values[hoveredIndex] - previous; const selectedX = x(hoveredIndex); const selectedY = y(values[hoveredIndex]); ctx.save(); ctx.setLineDash([4, 5]); ctx.strokeStyle = 'rgba(245,241,232,.48)'; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(selectedX, padding); ctx.lineTo(selectedX, height - padding); ctx.stroke(); ctx.setLineDash([]); ctx.beginPath(); ctx.arc(selectedX, selectedY, 6, 0, Math.PI * 2); ctx.fillStyle = '#111110'; ctx.fill(); ctx.strokeStyle = '#d5ff52'; ctx.lineWidth = 2; ctx.stroke(); ctx.restore(); const sign = movement > 0 ? '+' : ''; document.getElementById('tooltip-price').textContent = Math.round(values[hoveredIndex] * 100) + '¢ YES'; const detail = document.getElementById('tooltip-detail'); detail.textContent = (hoveredIndex === 0 ? 'Market open' : sign + (movement * 100).toFixed(1) + '¢') + ' · ' + (selected.kind === 'DEMO' ? 'demo pulse' : selected.kind === 'TRADE' ? 'trade' : 'market open'); detail.className = movement > 0 ? 'tooltip-up' : movement < 0 ? 'tooltip-down' : ''; document.getElementById('tooltip-time').textContent = new Intl.DateTimeFormat(undefined, {month:'short', day:'numeric', hour:'numeric', minute:'2-digit'}).format(new Date(selected.recordedAt)); tooltip.style.left = Math.min(width - 78, Math.max(78, selectedX)) + 'px'; tooltip.style.top = selectedY + 'px'; tooltip.classList.toggle('below', selectedY < 74); tooltip.classList.add('visible'); tooltip.setAttribute('aria-hidden', 'false'); } else { tooltip.classList.remove('visible'); tooltip.setAttribute('aria-hidden', 'true'); } const last = values[values.length - 1]; ctx.beginPath(); ctx.arc(x(values.length - 1), y(last), 4, 0, Math.PI * 2); ctx.fillStyle = '#d5ff52'; ctx.fill(); document.getElementById('chart-value').textContent = Math.round(last * 100) + '¢ now'; document.getElementById('chart-start').textContent = new Intl.DateTimeFormat(undefined, {month:'short', day:'numeric', hour:'numeric', minute:'2-digit'}).format(new Date(times[0])); };
        let refreshInFlight = false; let refreshQueued = false; let lastMarketRefresh = 0;
        const refresh = async () => { if (refreshInFlight) { refreshQueued = true; return; } refreshInFlight = true; try { const requests = [fetch('/api/markets/' + id), fetch('/api/markets/' + id + '/history')]; if (canTrade) requests.push(fetch('/api/me')); const results = await Promise.all(requests); const response = results[0]; const history = results[1]; const account = results[2]; if (!response.ok) return; const data = await response.json(); position = data.position || {yesShares: 0, noShares: 0}; document.getElementById('yes-price').textContent = Math.round(data.priceYes * 100) + '¢'; document.getElementById('no-price').textContent = Math.round(data.priceNo * 100) + '¢'; if (canTrade) document.getElementById('position-shares').textContent = position.yesShares.toFixed(1) + ' YES · ' + position.noShares.toFixed(1) + ' NO'; document.getElementById('liquidity-depth').textContent = Math.round(data.metrics.liquidityDepth).toLocaleString() + ' cr'; document.getElementById('volatility').textContent = formatVolatility(data.metrics.volatility); document.getElementById('activity-count').textContent = data.metrics.activityCount + ' ticks'; document.getElementById('pulse-label').textContent = '● local demo flow · ' + data.metrics.demoActivityCount + ' ticks'; if (canTrade && account.ok) { const value = await account.json(); document.getElementById('wallet-balance').textContent = money(value.account.availableBalance); } if (history.ok) { points = (await history.json()).points; drawChart(); } syncTradeForm(); lastMarketRefresh = Date.now(); } catch {} finally { refreshInFlight = false; if (refreshQueued) { refreshQueued = false; window.setTimeout(() => void refresh(), Math.max(0, 1_000 - (Date.now() - lastMarketRefresh))); } } };
        if (canTrade) { document.querySelectorAll('[data-outcome]').forEach(button => button.addEventListener('click', () => { outcome = button.dataset.outcome; syncTradeForm(); })); document.querySelectorAll('[data-mode]').forEach(button => button.addEventListener('click', () => { mode = button.dataset.mode; syncTradeForm(); })); document.querySelectorAll('[data-spend]').forEach(button => button.addEventListener('click', () => { amountInput.value = button.dataset.spend; })); form.addEventListener('submit', async event => { event.preventDefault(); const button = form.querySelector('.trade'); const amount = Number(amountInput.value); const selling = mode === 'SELL'; button.disabled = true; notice.className = 'notice'; notice.textContent = selling ? 'Finding exit price…' : 'Placing trade…'; try { const response = await fetch('/api/markets/' + id + (selling ? '/sells' : '/trades'), { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify(selling ? {outcome, shares: amount} : {outcome, credits: amount}) }); const payload = await response.json(); if (!response.ok) throw new Error(payload.error?.message || 'Trade failed'); notice.className = 'notice ok'; notice.textContent = selling ? 'Sold ' + payload.trade.shares.toFixed(1) + ' ' + outcome + ' shares for ' + payload.trade.credits.toFixed(1) + ' credits.' : 'Bought ' + payload.trade.shares.toFixed(1) + ' ' + outcome + ' shares.'; await refresh(); } catch (error) { notice.className = 'notice error'; notice.textContent = error.message; } finally { button.disabled = false; } }); }
        const events = new EventSource('/events'); ['market.trade.executed', 'market.demo.pulse', 'market.resolved'].forEach(type => events.addEventListener(type, event => { const data = JSON.parse(event.data); if (data.marketId === id) refresh(); }));
        chart.addEventListener('pointermove', event => { const bounds = chart.getBoundingClientRect(); const plotted = points.length ? points : [{recordedAt: new Date().toISOString()}]; const relativeX = Math.min(bounds.width, Math.max(0, event.clientX - bounds.left)); hoveredIndex = plotted.length === 1 ? 0 : Math.round(relativeX / Math.max(1, bounds.width) * (plotted.length - 1)); drawChart(); }); chart.addEventListener('pointerleave', () => { hoveredIndex = null; drawChart(); }); chart.addEventListener('pointerdown', event => { chart.setPointerCapture?.(event.pointerId); }); window.addEventListener('resize', drawChart); drawChart();
      })();
    </script>`, market.question, account);
}
